<section class="section"><div class="container" style="max-width:860px"><h1 class="section-title mb-4"><?= h($title) ?></h1><?php if (!$news): ?><div class="empty">暂无公告</div><?php endif; ?><?php foreach ($news as $item): ?><article class="card card-hover p-4 mb-3"><div class="d-flex justify-content-between gap-3"><h2 class="h5 mb-2"><?= h($item['title']) ?></h2><time class="small text-muted"><?= h($item['create_time'] ? date('Y-m-d', $item['create_time']) : '') ?></time></div><p class="text-muted mb-0"><?= h(mb_substr(strip_tags($item['content']), 0, 180)) ?></p><a class="stretched-link" href="<?= h(url_to('index/index/article', ['id' => $item['id']])) ?>">阅读全文</a></article><?php endforeach; ?></div></section>
